'use strict';
const player={x:605,y:460,tx:605,ty:460,moving:false,facing:1},keys=new Set();let pending=null,transitioning=false,nearby=null,arrival=0;
const oldInteract=interact,oldUpdate=update,oldModal=modal;
modal=function(html){$('#overlay').classList.remove('titlemenu');oldModal(html);keys.clear();pending=null;player.tx=player.x;player.ty=player.y};
menu=function(){save();modal(`<div class="eyebrow">작은 농장, 커다란 도전</div><div class="illustration">🥚</div><h1>계란으로<br>바위치기</h1><p>내일도, 우리 농장엔 달걀이 생기니까.</p><div class="buttons"><button class="primary" data-action="start">${S.started?'계속 모험하기':'모험 시작하기'}</button><button data-action="settings">설정 · 이야기</button><button data-action="exit">저장하고 나가기</button></div><p style="font-size:11px;opacity:.8">WASD / 방향키로 이동 · 땅을 눌러 걸어가기</p>`);$('#overlay').classList.add('titlemenu')};
function destinations(){if(view==='farm')return [{x:612,y:564,r:85,label:'마을길로 나가기',kind:'village'},{x:915,y:282,r:85,label:'부화장 열기',kind:'incubator'},{x:477,y:288,r:65,label:'닭 살펴보기',kind:'chickens'},{x:790,y:408,r:65,label:'깨끗한 물로 갈기',kind:'water'}];if(view==='village')return [{x:217,y:375,r:90,label:'양계장으로 들어가기',kind:'farm'},{x:776,y:383,r:85,label:'잡화점으로 들어가기',kind:'shop'},{x:583,y:194,r:80,label:'산길을 따라 올라가기',kind:'mountain'}];if(view==='shop')return [{x:549,y:471,r:100,label:'상인과 이야기하기',kind:'shopMenu'},{x:550,y:592,r:65,label:'마을길로 돌아가기',kind:'village'}];if(view==='mountain'&&rockIndex===null)return [{x:550,y:596,r:60,label:'마을로 내려가기',kind:'village'}];return []}
function travel(next){if(transitioning)return;transitioning=true;pending=null;keys.clear();$('#fade').classList.add('dark');setTimeout(()=>{view=next;rockIndex=null;mode='walk';const spawn={farm:[612,511],village:[510,466],shop:[550,545],mountain:[550,567]}[next];player.x=player.tx=spawn[0];player.y=player.ty=spawn[1];arrival=2;update();$('#fade').classList.remove('dark');transitioning=false;},250)}
function activate(d){if(!d)return;if(d.kind==='shopMenu')shop();else if(d.kind==='incubator')incubator();else if(d.kind==='chickens')chickenList();else if(d.kind==='water'){S.water=100;save();update();toast('물을 깨끗하게 갈았어요.');beep(600)}else if(d.kind==='rock'){rockIndex=d.index;player.x=player.tx=550;player.y=player.ty=593;pending=null;update()}else travel(d.kind)}
function playerStep(dt){if(transitioning)return;arrival=Math.max(0,arrival-dt);if(view==='mountain'&&rockIndex!==null){player.moving=false;$('#context').classList.add('hidden');return}let dx=(keys.has('d')||keys.has('ArrowRight')?1:0)-(keys.has('a')||keys.has('ArrowLeft')?1:0),dy=(keys.has('s')||keys.has('ArrowDown')?1:0)-(keys.has('w')||keys.has('ArrowUp')?1:0);if(dx||dy){pending=null;const len=Math.hypot(dx,dy);player.tx=player.x+dx/len*100;player.ty=player.y+dy/len*100}const minY=view==='farm'?285:view==='shop'?440:190;player.tx=clamp(player.tx,view==='farm'?145:70,view==='farm'?950:1030);player.ty=clamp(player.ty,minY,605);const dist=Math.hypot(player.tx-player.x,player.ty-player.y);player.moving=dist>3;if(player.moving){const step=Math.min(dt*170,dist);if(Math.abs(player.tx-player.x)>1)player.facing=player.tx>player.x?1:-1;player.x+=(player.tx-player.x)/dist*step;player.y+=(player.ty-player.y)/dist*step}if(pending&&Math.hypot(player.x-pending.x,player.y-pending.y)<18){const d=pending;pending=null;activate(d)}nearby=destinations().find(d=>Math.hypot(d.x-player.x,d.y-player.y)<d.r);const button=$('#context');if(nearby&&!pending){button.textContent=`E  ${nearby.label}`;button.classList.remove('hidden')}else button.classList.add('hidden')}
interact=function(p){if(transitioning)return;if(view==='mountain'&&rockIndex!==null){oldInteract(p);return}if(mode!=='walk'&&view==='farm'){oldInteract(p);return}let target=destinations().find(d=>Math.hypot(d.x-p.x,d.y-p.y)<d.r);if(view==='mountain'&&rockIndex===null){for(let i=0;i<12;i++){const rp=rockMapPos(i);if(!S.rocks[i].broken&&Math.hypot(rp.x-p.x,rp.y-p.y)<60)target={...rp,y:rp.y+26,kind:'rock',index:i}}}if(view==='farm'&&!target){for(let i=0;i<4;i++){const x=295+i*120;if(S.nests[i]&&Math.hypot(p.x-x,p.y-245)<50){collect(i);return}}}if(target){pending=target;player.tx=target.x;player.ty=target.y;return}pending=null;player.tx=p.x;player.ty=p.y;burst(p.x,p.y,'#fff2ae',4)};
update=function(){const broken=S.rocks.filter(r=>r.broken).length;$('#resources').innerHTML=`<div class="resource">◉ <b>${S.coins.toLocaleString()}</b></div><div class="resource">🥚 <b>${S.eggs.length}</b><span class="badge"> / ${capacity()}</span></div>`;$('#day').innerHTML=`☀ ${Math.floor(S.seconds/180)+1}일째<br><span class="badge">${S.seconds%180<120?'햇살 좋은 낮':'노을 지는 오후'}</span>`;$('#sceneLabel').textContent={farm:'햇살 양계장',village:'바람꽃 마을',shop:'숲길 잡화점',mountain:rockIndex===null?'바위산':S.rocks[rockIndex].name}[view];$('#quest').innerHTML=`<b>작은 달걀의 큰 모험</b>산의 바위 ${broken} / 12개 격파${view==='farm'?'<br>닭 '+S.chickens.length+'마리와 함께하는 하루':''}`;const hunger=S.chickens.length?Math.round(S.chickens.reduce((a,c)=>a+c.hunger,0)/S.chickens.length):0;$('#care').innerHTML=view==='farm'?`<span>🌾 ${hunger}%</span><span>💧 ${Math.round(S.water)}%</span><span>✧ ${Math.round(cleanPercent())}%</span>`:'';
let note='땅을 클릭해 걸어가거나, WASD / 방향키로 움직이세요';if(view==='farm')note={walk:'둥지를 눌러 알을 줍고, 아래쪽 문으로 나가 마을을 둘러보세요',collect:'둥지에 놓인 달걀을 클릭하세요',feed:'먹이통을 채우거나 땅에 먹이를 뿌려 주세요',clean:'누른 채 쓱쓱 움직여 청소하세요',heal:'병든 닭을 클릭해 주사를 놓으세요'}[mode];if(view==='village')note='왼쪽은 우리 농장 · 오른쪽은 상점 · 위쪽 산길은 바위산';if(view==='shop')note='상점 문 앞에서 E · 아래쪽 길로 나가면 마을';if(view==='mountain')note=rockIndex===null?'바위를 클릭하면 그 앞으로 걸어갑니다':S.eggs.length?'바위를 클릭해서 달걀 던지기 · 바깥을 누르면 빗나가요':'달걀을 다 썼어요. 발걸음을 돌려 농장으로 돌아가세요';$('#sceneNote').textContent=note;
if(view==='farm')$('#toolbar').innerHTML=[['walk','✋','걷기'],['collect','🥚','수거'],['feed','🌾','먹이'],['clean','🧹','청소'],['heal','💉','주사']].map(([m,icon,label],i)=>`<button data-mode="${m}" title="${label} (${i+1})" class="${mode===m?'active':''}"><kbd>${i+1}</kbd>${icon}<small>${label}</small></button>`).join('');else if(view==='mountain'&&rockIndex!==null)$('#toolbar').innerHTML=`<button data-action="trail" title="산길로 돌아가기">↩<small>산길로</small></button><button data-action="ammo" title="던질 달걀 선택">🥚<small>달걀 선택</small></button>`;else $('#toolbar').innerHTML='<button class="active" data-mode="walk">✋<small>걷기</small></button>';if(S.chickens.some(c=>c.sick))$('#quest').innerHTML+='<br><span style="color:#ffe3aa">✚ 아픈 닭이 있어요. 주사가 필요해요.</span>';};
function bag(){modal(`<h2>나의 가방</h2><p>달걀 ${S.eggs.length} / ${capacity()}칸 · ${S.coins} G</p>${counts().map((n,i)=>n?`<div class="eggrow"><span style="background:${eggColors[i]};width:18px;height:25px;border-radius:50%"></span>${eggNames[i]}<b>${n}개</b></div>`:'').join('')||'<p>아직 달걀이 없어요. 둥지를 확인해 보세요.</p>'}<p>🌾 일반 먹이 ${S.food} · 좋은 먹이 ${S.premium}<br>💉 주사 ${S.meds}개 · 💎 광물 ${S.minerals.length}개</p>${view==='shop'?'<div class="buttons"><button data-action="sellEggs">달걀 팔기</button><button data-action="sellMinerals">광물 모두 팔기</button></div>':'<p>판매는 마을 상점에서 할 수 있어요.</p>'}<button class="full primary" data-action="close">가방 닫기</button>`)}
function ammo(){modal(`<h2>어떤 달걀을 던질까요?</h2>${counts().map((n,i)=>n?`<button class="full ${S.selectedEgg===i?'primary':''}" data-ammo="${i}">${eggNames[i]} ${n}개 · 공격력 ${(i+1)**2}~${5*(i+1)**2}</button>`:'').join('')||'<p>달걀이 없어요. 농장에서 수거해 주세요.</p>'}<button class="full" data-action="close">돌아가기</button>`)}
const baseShop=shop;shop=function(){baseShop();$('#overlay .modal').insertAdjacentHTML('beforeend','<div class="buttons"><button data-action="sellEggs">🥚 달걀 판매</button><button data-action="sellMinerals">💎 광물 판매</button></div>')};
function journal(){modal(`<h2>농장 주인의 수첩</h2><p>닭 ${S.chickens.length} / ${chickenCap()}마리 · 농장 Lv.${S.farm}</p>${stat('물',Math.round(S.water))}${stat('청결',Math.round(cleanPercent()))}<p>창고 ${S.eggs.length} / ${capacity()} · 부화장 ${S.incubators.length} / ${S.coop}<br>바위 ${S.rocks.filter(r=>r.broken).length} / 12개 · 명중 ${S.hits}회</p><div class="buttons"><button data-action="chickens">닭 살펴보기</button>${view==='farm'?'<button data-action="incubator">부화장</button>':''}</div><p>WASD / 방향키: 이동 · 1~5: 도구 · E: 상호작용<br>B: 가방 · J: 수첩 · M: 지도 · ESC: 일시정지</p><button class="full primary" data-action="close">수첩 덮기</button>`)}
