$('#context').onclick=()=>activate(nearby);
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;const a=b.dataset.action;if(a==='bag')bag();if(a==='journal')journal();if(a==='worldmap')worldmap();if(a==='ammo')ammo();if(a==='trail'){rockIndex=null;player.x=player.tx=550;player.y=player.ty=560;update()}if(b.dataset.ammo!==undefined){S.selectedEgg=+b.dataset.ammo;closeModal();toast(eggNames[S.selectedEgg]+'을 손에 들었어요.')}if(a==='start'){player.x=player.tx=605;player.y=player.ty=465;mode='walk';$('#overlay').classList.remove('titlemenu');update()}if(b.dataset.mode){pending=null;update()}});
document.addEventListener('keydown',e=>{if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight',' '].includes(e.key))e.preventDefault();if(paused)return;const k=e.key.length===1?e.key.toLowerCase():e.key;keys.add(k);if(e.repeat)return;if(k==='e')activate(nearby);if(k==='b')bag();if(k==='j')journal();if(k==='m')worldmap();if('12345'.includes(k)&&view==='farm'){mode=['walk','collect','feed','clean','heal'][+k-1];update()}});document.addEventListener('keyup',e=>{const k=e.key.length===1?e.key.toLowerCase():e.key;keys.delete(k);if(['w','a','s','d','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(k)&&!keys.size&&!pending){player.tx=player.x;player.ty=player.y}});window.addEventListener('blur',()=>keys.clear());document.addEventListener('visibilitychange',()=>keys.clear());document.querySelectorAll('[data-dir]').forEach(b=>{const k={up:'w',left:'a',down:'s',right:'d'}[b.dataset.dir];b.addEventListener('pointerdown',e=>{e.preventDefault();b.setPointerCapture(e.pointerId);keys.add(k)});b.addEventListener('pointerup',()=>keys.delete(k));b.addEventListener('pointercancel',()=>keys.delete(k))});
