// A real camera keeps world proportions intact on portrait and narrow screens.
let camera={scale:1,x:0,y:0};
function prepareView(){const w=cv.clientWidth||1100,h=cv.clientHeight||650;if(cv.width!==w||cv.height!==h){cv.width=w;cv.height=h}const scale=Math.max(w/1100,h/650),visibleW=w/scale,visibleH=h/scale;const focusX=paused?550:player.x,focusY=paused?325:player.y;camera={scale,x:clamp(focusX-visibleW/2,0,1100-visibleW),y:clamp(focusY-visibleH/2,0,650-visibleH)};ctx.setTransform(scale,0,0,scale,-camera.x*scale,-camera.y*scale)}
coords=function(e){const r=cv.getBoundingClientRect();return {x:(e.clientX-r.left)/camera.scale+camera.x,y:(e.clientY-r.top)/camera.scale+camera.y}};
